            throw new Error("Failed to set display name");
        });
    };

    public render(): JSX.Element {
        return (
            <EditableTextContainer
                getInitialValue={this.getDisplayName}
                placeholder={_t("No display name")}
                blurToSubmit={true}
                onSubmit={this.changeDisplayName} />
        );
    }
}

