 31	export const DeviceDetailHeading: React.FC<Props> = ({ device, saveDeviceName }) => {
 32	    const [isEditing, setIsEditing] = useState(false);
 33	    const [deviceName, setDeviceName] = useState('');
 34	    const [savedName, setSavedName] = useState<string>();
 35	    const [isSaving, setIsSaving] = useState(false);
 36	    const [error, setError] = useState(false);
 37	
 38	    useEffect(() => {
 39	        setSavedName(undefined);
 40	    }, [device.device_id, device.display_name]);
 41	
 42	    const displayedName = savedName ?? device.display_name ?? device.device_id;
 43	
 44	    const onRename = (): void => {
 45	        setDeviceName(displayedName);
 46	        setError(false);
 47	        setIsEditing(true);
 48	    };
 49	
 50	    const onCancel = (): void => {
 51	        setDeviceName(displayedName);
 52	        setError(false);
 53	        setIsEditing(false);
 54	    };
 55	
 56	    const saveName = async (): Promise<void> => {
 57	        if (isSaving) return;
 58	
 59	        setError(false);
 60	        if (deviceName === displayedName) {
 61	            setIsEditing(false);
 62	            return;
 63	        }
 64	
 65	        setIsSaving(true);
 66	        try {
 67	            await saveDeviceName(device.device_id, deviceName);
 68	            setSavedName(deviceName);
 69	            setIsEditing(false);
 70	        } catch (error) {
 71	            setError(true);
 72	        } finally {
 73	            setIsSaving(false);
 74	        }
 75	    };
 76	
 77	    const onSubmit = (event: FormEvent<HTMLFormElement>): void => {
 78	        event.preventDefault();
 79	        void saveName();
 80	    };
 81	
 82	    return <div className='mx_DeviceDetailHeading' data-testid='device-detail-heading'>
 83	        { isEditing
 84	            ? <form
 85	                className='mx_DeviceDetailHeading_editView'
 86	                data-testid='device-detail-heading-edit'
 87	                onSubmit={onSubmit}
 88	            >
 89	                <Field
 90	                    label={_t('Session name')}
 91	                    type='text'
 92	                    value={deviceName}
 93	                    maxLength={100}
 94	                    autoComplete='off'
 95	                    autoFocus
 96	                    data-testid='device-detail-heading-input'
 97	                    onChange={(event) => setDeviceName(event.target.value)}
 98	                />
 99	                <p className='mx_DeviceDetailHeading_disclosure'>
100	                    { _t('Session names may be visible to people you communicate with.') }
101	                </p>
102	                { error && <div
103	                    className='mx_DeviceDetailHeading_error'
104	                    data-testid='device-detail-heading-error'
105	                    role='alert'
106	                >
107	                    Failed to set display name.
108	                </div> }
109	                <div className='mx_DeviceDetailHeading_actions'>
110	                    <AccessibleButton
111	                        element='button'
112	                        type='submit'
113	                        kind='primary'
114	                        disabled={isSaving}
115	                        data-testid='device-detail-heading-save'
116	                        onClick={(event) => {
117	                            event?.preventDefault();
118	                            void saveName();
119	                        }}
120	                    >
121	                        { _t('Save') }
122	                    </AccessibleButton>
123	                    <AccessibleButton
124	                        element='button'
125	                        type='button'
126	                        kind='secondary'
127	                        disabled={isSaving}
128	                        data-testid='device-detail-heading-cancel'
129	                        onClick={onCancel}
130	                    >
131	                        { _t('Cancel') }
132	                    </AccessibleButton>
133	                    { isSaving && <Spinner w={16} h={16} message={_t('Saving...')} /> }
134	                </div>
135	            </form>
136	            : <div
137	                className='mx_DeviceDetailHeading_readView'
138	                data-testid='device-detail-heading-read'
139	            >
140	                <Heading size='h3'>{ displayedName }</Heading>
141	                <AccessibleButton
142	                    kind='link_inline'
143	                    onClick={onRename}
144	                    data-testid='device-detail-heading-rename'
145	                >
146	                    { _t('Rename') }
147	                </AccessibleButton>
148	            </div>
149	        }
150	    </div>;
151	};
152	
153	export default DeviceDetailHeading;

