 76	export type DevicesState = {
 77	    devices: DevicesDictionary;
 78	    currentDeviceId: string;
 79	    isLoading: boolean;
 80	    // not provided when current session cannot request verification
 81	    requestDeviceVerification?: (deviceId: DeviceWithVerification['device_id']) => Promise<VerificationRequest>;
 82	    refreshDevices: () => Promise<void>;
 83	    saveDeviceName: (deviceId: string, deviceName: string) => Promise<void>;
 84	    error?: OwnDevicesError;
 85	};
 86	export const useOwnDevices = (): DevicesState => {
 87	    const matrixClient = useContext(MatrixClientContext);
 88	
 89	    const currentDeviceId = matrixClient.getDeviceId();
 90	    const userId = matrixClient.getUserId();
 91	
 92	    const [devices, setDevices] = useState<DevicesState['devices']>({});
 93	    const [isLoading, setIsLoading] = useState(true);
 94	    const [error, setError] = useState<OwnDevicesError>();
 95	
 96	    const refreshDevices = useCallback(async () => {
 97	        setIsLoading(true);
 98	        try {
 99	            // realistically we should never hit this
100	            // but it satisfies types
101	            if (!userId) {
102	                throw new Error('Cannot fetch devices without user id');
103	            }
104	            const devices = await fetchDevicesWithVerification(matrixClient, userId);
105	            setDevices(devices);
106	            setIsLoading(false);
107	        } catch (error) {
108	            if ((error as MatrixError).httpStatus == 404) {
109	                // 404 probably means the HS doesn't yet support the API.
110	                setError(OwnDevicesError.Unsupported);
111	            } else {
112	                logger.error("Error loading sessions:", error);
113	                setError(OwnDevicesError.Default);
114	            }
115	            setIsLoading(false);
116	        }
117	    }, [matrixClient, userId]);
118	
119	    const saveDeviceName = useCallback(async (deviceId: string, deviceName: string): Promise<void> => {
120	        try {
121	            await matrixClient.setDeviceDetails(deviceId, { display_name: deviceName });
122	            setDevices(currentDevices => {
123	                const device = currentDevices[deviceId];
124	                if (!device) {
125	                    return currentDevices;
126	                }
127	                return {
128	                    ...currentDevices,
129	                    [deviceId]: {
130	                        ...device,
131	                        display_name: deviceName,
132	                    },
133	                };
134	            });
135	        } catch (error) {
136	            logger.error("Error setting session display name", error);
137	            throw new Error("Failed to set display name.");
138	        }
139	    }, [matrixClient]);
140	
141	    useEffect(() => {
142	        refreshDevices();
143	    }, [refreshDevices]);
144	
145	    const isCurrentDeviceVerified = !!devices[currentDeviceId]?.isVerified;
146	
147	    const requestDeviceVerification = isCurrentDeviceVerified && userId
148	        ? async (deviceId: DeviceWithVerification['device_id']) => {
149	            return await matrixClient.requestVerification(
150	                userId,
151	                [deviceId],
152	            );
153	        }
154	        : undefined;
155	
156	    return {
157	        devices,
158	        currentDeviceId,
159	        requestDeviceVerification,
160	        refreshDevices,
161	        saveDeviceName,
162	        isLoading,
163	        error,
164	    };
165	};
